def check_solution(y):
    # We are looking for integer roots z >= y for:
    # z^3 - y^2 * z^2 + (1 + y^3) = 0

    # We can search up to a reasonable limit for z, e.g., 3*y + 5
    max_z = 3 * y + 5

    for z in range(y, max_z + 1):
        LHS = z**3 - y**2 * z**2 + (1 + y**3)
        if LHS == 0:
            return (1, y, z)
    return None

for y in range(1, 6): # Test y=1 through y=5
    solution = check_solution(y)
    if solution:
        print(f"Solution found for y={y}: {solution}")

def find_solutions_final():
    solutions = []
    for x in range(1, 10):
        for y in range(x, 10):
            max_k = min(2 * y, x**2 * y**2 - y)
            if max_k < 1: continue
            for k in range(1, max_k + 1):
                if (x**3 + y**3) % k == 0:
                    z2 = (x**3 + y**3) // k
                    z = int(z2**0.5)
                    if z * z == z2:
                        if x**2 * y**2 - k == z and z >= y:
                            solutions.append((x, y, z))
    return solutions

print(find_solutions_final())
